def compute(vars):
    non_us_gcla = vars["v1"]
    total_gcla = vars["v2"]
    if total_gcla == 0:
        return None
    percentage = non_us_gcla / total_gcla * 100
    return {
        "value": percentage,
        "trace": {
            "non_us_gcla": non_us_gcla,
            "total_gcla": total_gcla,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
